import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Entitäten","description":"","frontmatter":{},"headers":[],"relativePath":"projects/fritzbox-to-mqtt/entitaeten.md","filePath":"projects/fritzbox-to-mqtt/entitaeten.md","lastUpdated":1793113714000}'),a={name:"projects/fritzbox-to-mqtt/entitaeten.md"};function l(o,e,d,u,s,c){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="entitaten" tabindex="-1">Entitäten <a class="header-anchor" href="#entitaten" aria-label="Permalink to &quot;Entitäten&quot;">​</a></h1><p>Die Entitäten werden per MQTT Discovery erstellt.</p><h2 id="anrufbeantworter" tabindex="-1">Anrufbeantworter <a class="header-anchor" href="#anrufbeantworter" aria-label="Permalink to &quot;Anrufbeantworter&quot;">​</a></h2><p>Für erkannte Anrufbeantworter werden Entitäten von <code>AB0</code> bis <code>AB4</code> angelegt:</p><ul><li>neue Nachrichten</li><li>alte Nachrichten</li><li>Status</li><li>Ein/Aus-Schalter</li></ul><p>Der FRITZ!Box-Name des Anrufbeantworters wird als Attribut geführt, aber nicht für die Entitätsnamen verwendet.</p><h2 id="wlan" tabindex="-1">WLAN <a class="header-anchor" href="#wlan" aria-label="Permalink to &quot;WLAN&quot;">​</a></h2><p>Je nach FRITZ!Box werden angelegt:</p><ul><li>WLAN 2,4 GHz Ein/Aus</li><li>WLAN 2,4 GHz Status</li><li>WLAN 5 GHz Ein/Aus</li><li>WLAN 5 GHz Status</li><li>WLAN Gast Ein/Aus</li><li>WLAN Gast Status</li></ul><p>Die WLAN-Statussensoren zeigen <code>Ein</code> oder <code>Aus</code>; der rohe FRITZ!Box-Status bleibt als Attribut erhalten.</p><h2 id="wan-und-box-status" tabindex="-1">WAN und Box-Status <a class="header-anchor" href="#wan-und-box-status" aria-label="Permalink to &quot;WAN und Box-Status&quot;">​</a></h2><ul><li>Verbindung Download</li><li>Verbindung Upload</li><li>Downloadrate</li><li>Uploadrate</li><li>WAN Link Status</li><li>Box Mesh Rolle</li><li>Box PPP Verbindung</li><li>Box PPP IPv4 Extern</li><li>Box IPv6 Extern</li><li>Box DECT</li><li>Box DNS over TLS</li></ul><p><code>WAN Link Status</code> zeigt ebenfalls <code>Ein</code> oder <code>Aus</code>.</p><p>Nicht von der FRITZ!Box gelieferte optionale Werte werden ausgeblendet oder als <code>unknown</code> veröffentlicht.</p><h2 id="anruflisten-und-live-anrufmonitor" tabindex="-1">Anruflisten und Live-Anrufmonitor <a class="header-anchor" href="#anruflisten-und-live-anrufmonitor" aria-label="Permalink to &quot;Anruflisten und Live-Anrufmonitor&quot;">​</a></h2><p>Konfigurierbare Anruflisten:</p><ul><li>alle Anrufe</li><li>eingehende Anrufe</li><li>ausgehende Anrufe</li><li>verpasste Anrufe</li><li>abgewiesene Anrufe</li><li>gesperrte Anrufe</li></ul><p>Der Live-Anrufmonitor liefert Ereignisse wie <code>RING</code>, <code>CALL</code>, <code>CONNECT</code> und <code>DISCONNECT</code>.</p><h2 id="telefonbucher" tabindex="-1">Telefonbücher <a class="header-anchor" href="#telefonbucher" aria-label="Permalink to &quot;Telefonbücher&quot;">​</a></h2><p>Telefonbücher werden mit den erkannten FRITZ!Box-Namen angezeigt. Tellows-Sperrlisten können über Namensfilter ausgeblendet oder über <code>phonebook_names</code> sinnvoll benannt werden.</p><h2 id="dect" tabindex="-1">DECT <a class="header-anchor" href="#dect" aria-label="Permalink to &quot;DECT&quot;">​</a></h2><p>Optional werden pro erkanntem DECT-Handset veröffentlicht:</p><ul><li>interne Nummer</li><li>Geräte-ID</li></ul><p><code>NoRingTime</code> wird bewusst nicht mehr veröffentlicht.</p>',24)])])}const b=t(a,[["render",l]]);export{f as __pageData,b as default};
